// -------------------------------
// Full Screen Toggle Script for SAC Analytic Application
// -------------------------------

// Define object names (actual names from your SAC app)
var pnl_header = Panel_6;   // Header panel
var pnl_filter = Panel_9;   // Filter panel
var pnl_table = Panel_8;    // Table panel
var btn_fullscreen = Button_15; // Fullscreen toggle button

// Track fullscreen state
var isFullScreen = false;

// Fullscreen toggle function
btn_fullscreen.onClick(() => {
    if (!isFullScreen) {
        // ENTER FULLSCREEN MODE
        pnl_header.setVisible(false);
        pnl_filter.setVisible(false);

        // Expand table panel to full screen (Canvas layout only)
        pnl_table.getLayout().setTop(LayoutValue.create(0, LayoutUnit.Pixel));
        pnl_table.getLayout().setLeft(LayoutValue.create(0, LayoutUnit.Pixel));
        pnl_table.getLayout().setRight(LayoutValue.create(0, LayoutUnit.Pixel));
        pnl_table.getLayout().setBottom(LayoutValue.create(0, LayoutUnit.Pixel));
        pnl_table.getLayout().setWidth(LayoutValue.create(100, LayoutUnit.Percent));
        pnl_table.getLayout().setHeight(LayoutValue.create(100, LayoutUnit.Percent));

        // Update button label & tooltip
        btn_fullscreen.setText('Exit Fullscreen');
        btn_fullscreen.setTooltip('Exit full screen mode');

        isFullScreen = true;
    } else {
        // EXIT FULLSCREEN MODE
        pnl_header.setVisible(true);
        pnl_filter.setVisible(true);

        // Restore table panel layout (your original position)
        pnl_table.getLayout().setTop(LayoutValue.create(47, LayoutUnit.Pixel));
        pnl_table.getLayout().setLeft(LayoutValue.create(186, LayoutUnit.Pixel));
        pnl_table.getLayout().setWidth(LayoutValue.create(1141, LayoutUnit.Pixel));
        pnl_table.getLayout().setHeight(LayoutValue.create(370, LayoutUnit.Pixel));

        // Update button label & tooltip
        btn_fullscreen.setText('Enter Fullscreen');
        btn_fullscreen.setTooltip('View table in full screen');

        isFullScreen = false;
    }
});
